const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-110.517217, 45.506013]);
  const roi = point.buffer(3000); // 3km radius

  const aug2012Start = '2012-08-10';
  const aug2012End = '2012-08-20';
  const sep2012Start = '2012-09-10';
  const sep2012End = '2012-09-20';

  // 2. Data Acquisition - Landsat 7
  function maskClouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(cloudMask);
  }

  function addNBR(image) {
    const nir = image.select('SR_B4');
    const swir2 = image.select('SR_B7');
    const nbr = nir.subtract(swir2).divide(nir.add(swir2)).rename('NBR');
    return image.addBands(nbr);
  }

  let colAug = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(roi)
    .filterDate(aug2012Start, aug2012End)
    .map(maskClouds)
    .map(addNBR);

  let colSep = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(roi)
    .filterDate(sep2012Start, sep2012End)
    .map(maskClouds)
    .map(addNBR);

  const augSize = colAug.size().getInfo();
  const sepSize = colSep.size().getInfo();

  console.log(`August 2012 Images: ${augSize}`);
  console.log(`September 2012 Images: ${sepSize}`);

  if (augSize === 0 || sepSize === 0) {
    console.log("Missing data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Create median composites
  const augImage = colAug.median().select('NBR');
  const sepImage = colSep.median().select('NBR');

  // 4. Check pixel counts
  const augCount = augImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const sepCount = sepImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  console.log(`August valid pixels: ${augCount}`);
  console.log(`September valid pixels: ${sepCount}`);

  if (augCount === 0 || sepCount === 0) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Calculate burn scar area (NBR < 0.1 threshold)
  const burnThreshold = 0.1;
  const augBurnMask = augImage.lt(burnThreshold);
  const sepBurnMask = sepImage.lt(burnThreshold);

  const augBurnArea = augBurnMask.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const sepBurnArea = sepBurnMask.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  console.log(`August burn scar area: ${(augBurnArea / 1e6).toFixed(2)} km²`);
  console.log(`September burn scar area: ${(sepBurnArea / 1e6).toFixed(2)} km²`);

  // 6. Validation & Final Answer
  if (augBurnArea === null || sepBurnArea === null || isNaN(augBurnArea) || isNaN(sepBurnArea)) {
    console.log("Calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  const increase = sepBurnArea - augBurnArea;
  console.log(`Change in burn scar: ${(increase / 1e6).toFixed(2)} km²`);

  if (increase > 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
